/**
 * Export and import serializers for note content (SPEC §6 / Phase 4).
 *
 * Export converts the editor's Tiptap JSON to txt/md/html/json. The HTML
 * output is generated by this module with strict escaping — untrusted note
 * content is never injected into the DOM raw (Section 16).
 *
 * Import parses md/txt via a small line-based markdown converter and json
 * via structural validation. Imported content flows through Tiptap's schema
 * on setContent, so anything the schema does not know is dropped — imported
 * files can never inject markup.
 */

import { z } from "zod"

interface TiptapMark {
  type: string
  attrs?: { href?: string }
}

interface TiptapNode {
  type?: string
  text?: string
  marks?: TiptapMark[]
  attrs?: { level?: number; checked?: boolean }
  content?: TiptapNode[]
}

export type ExportFormat = "txt" | "md" | "html" | "json"

function blocks(node: TiptapNode | undefined): TiptapNode[] {
  return node?.content ?? []
}

function inlineText(node: TiptapNode): string {
  if (node.text !== undefined) {
    return node.text
  }
  return (node.content ?? []).map(inlineText).join("")
}

// ---------------------------------------------------------------------------
// Plain text
// ---------------------------------------------------------------------------

export function toPlainText(doc: unknown): string {
  const out: string[] = []
  for (const block of blocks(doc as TiptapNode)) {
    out.push(...blockToPlain(block, 0))
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim()
}

function blockToPlain(node: TiptapNode, indent: number): string[] {
  const pad = "  ".repeat(indent)
  switch (node.type) {
    case "heading":
    case "paragraph":
      return [pad + inlineText(node)]
    case "codeBlock":
      return (node.content ?? []).map((line) => pad + inlineText(line))
    case "blockquote":
      return blocks(node).flatMap((child) =>
        blockToPlain(child, indent).map((line) => `> ${line}`)
      )
    case "bulletList":
    case "orderedList":
      return blocks(node).flatMap((item, index) => {
        const marker = node.type === "bulletList" ? "•" : `${index + 1}.`
        return blocks(item).flatMap((child) =>
          blockToPlain(child, indent + 1).map((line, i) =>
            i === 0 ? `${pad}${marker} ${line.trim()}` : line
          )
        )
      })
    case "horizontalRule":
      return [`${pad}—————————`]
    default:
      return node.content ? blocks(node).flatMap((c) => blockToPlain(c, indent)) : [pad + inlineText(node)]
  }
}

// ---------------------------------------------------------------------------
// Markdown
// ---------------------------------------------------------------------------

function marksToMarkdown(text: string, marks: TiptapMark[] | undefined): string {
  let out = text
  for (const mark of marks ?? []) {
    switch (mark.type) {
      case "bold":
        out = `**${out}**`
        break
      case "italic":
        out = `*${out}*`
        break
      case "strike":
        out = `~~${out}~~`
        break
      case "code":
        out = `\`${out}\``
        break
      case "highlight":
        out = `==${out}==`
        break
      case "link":
        out = `[${out}](${mark.attrs?.href ?? ""})`
        break
      default:
        break
    }
  }
  return out
}

function inlineMarkdown(node: TiptapNode): string {
  if (node.text !== undefined) {
    return marksToMarkdown(node.text, node.marks)
  }
  return (node.content ?? []).map(inlineMarkdown).join("")
}

export function toMarkdown(doc: unknown): string {
  const out: string[] = []
  let orderedIndex = 0
  let currentList: "bullet" | "ordered" | null = null

  const flushList = () => {
    currentList = null
    orderedIndex = 0
  }

  const render = (node: TiptapNode): void => {
    switch (node.type) {
      case "heading":
        flushList()
        out.push(`${"#".repeat(node.attrs?.level ?? 1)} ${inlineMarkdown(node)}`)
        break
      case "paragraph":
        flushList()
        out.push(inlineMarkdown(node))
        break
      case "codeBlock":
        flushList()
        out.push("```\n" + (node.content ?? []).map(inlineMarkdown).join("\n") + "\n```")
        break
      case "blockquote":
        flushList()
        out.push(
          blocks(node)
            .map((child) => `> ${inlineMarkdown(child)}`)
            .join("\n")
        )
        break
      case "bulletList":
        flushList()
        currentList = "bullet"
        blocks(node).forEach(render)
        flushList()
        break
      case "orderedList":
        flushList()
        currentList = "ordered"
        blocks(node).forEach((item) => {
          render(item)
          orderedIndex += 1
        })
        flushList()
        break
      case "listItem": {
        const marker = currentList === "ordered" ? `${orderedIndex + 1}.` : "-"
        const body = blocks(node)
          .map(inlineMarkdown)
          .join("\n")
        out.push(`${marker} ${body}`)
        break
      }
      case "taskList":
        flushList()
        blocks(node).forEach((item) => {
          const check = item.attrs?.checked ? "[x]" : "[ ]"
          out.push(`- ${check} ${blocks(item).map(inlineMarkdown).join(" ")}`)
        })
        break
      case "horizontalRule":
        flushList()
        out.push("---")
        break
      default:
        if (node.content) {
          blocks(node).forEach(render)
        } else {
          out.push(inlineMarkdown(node))
        }
    }
  }

  for (const block of blocks(doc as TiptapNode)) {
    render(block)
  }
  return out.join("\n\n").replace(/\n{3,}/g, "\n\n").trim()
}

// ---------------------------------------------------------------------------
// HTML
// ---------------------------------------------------------------------------

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
}

function inlineHtml(node: TiptapNode): string {
  if (node.text !== undefined) {
    let out = escapeHtml(node.text)
    for (const mark of node.marks ?? []) {
      switch (mark.type) {
        case "bold":
          out = `<strong>${out}</strong>`
          break
        case "italic":
          out = `<em>${out}</em>`
          break
        case "strike":
          out = `<del>${out}</del>`
          break
        case "code":
          out = `<code>${out}</code>`
          break
        case "highlight":
          out = `<mark>${out}</mark>`
          break
        case "link":
          out = `<a href="${escapeHtml(mark.attrs?.href ?? "")}" rel="noopener noreferrer nofollow">${out}</a>`
          break
        default:
          break
      }
    }
    return out
  }
  return (node.content ?? []).map(inlineHtml).join("")
}

export function toHtml(doc: unknown): string {
  const render = (node: TiptapNode): string => {
    const inner = (node.content ?? []).map(render).join("")
    switch (node.type) {
      case "heading": {
        const level = Math.min(Math.max(node.attrs?.level ?? 1, 1), 6)
        return `<h${level}>${inlineHtml(node)}</h${level}>`
      }
      case "paragraph":
        return `<p>${inlineHtml(node)}</p>`
      case "codeBlock":
        return `<pre><code>${(node.content ?? []).map(inlineHtml).join("\n")}</code></pre>`
      case "blockquote":
        return `<blockquote>${inner}</blockquote>`
      case "bulletList":
        return `<ul>${inner}</ul>`
      case "orderedList":
        return `<ol>${inner}</ol>`
      case "listItem":
        return `<li>${inner}</li>`
      case "taskList":
        return `<ul class="task-list">${inner}</ul>`
      case "taskItem": {
        const checked = node.attrs?.checked ? " checked" : ""
        return `<li class="task-item"><input type="checkbox" disabled${checked}> ${inner}</li>`
      }
      case "horizontalRule":
        return "<hr>"
      default:
        return node.content ? inner : escapeHtml(inlineText(node))
    }
  }
  return blocks(doc as TiptapNode).map(render).join("\n")
}

// ---------------------------------------------------------------------------
// JSON backup
// ---------------------------------------------------------------------------

export interface JsonBackup {
  app: "notra"
  version: 1
  title: string
  exportedAt: string
  content: unknown
}

export function toJsonBackup(title: string, doc: unknown): string {
  const backup: JsonBackup = {
    app: "notra",
    version: 1,
    title,
    exportedAt: new Date().toISOString(),
    content: doc,
  }
  return JSON.stringify(backup, null, 2)
}

// ---------------------------------------------------------------------------
// Import
// ---------------------------------------------------------------------------

const backupSchema = z.object({
  app: z.literal("notra").optional(),
  title: z.string().max(200).optional(),
  content: z.unknown(),
}).passthrough()

/** Structural validation of an untrusted Tiptap-JSON document. */
export function isTiptapDoc(value: unknown, depth = 0): boolean {
  if (depth > 64) {
    return false
  }
  if (typeof value !== "object" || value === null) {
    return false
  }
  const node = value as TiptapNode
  if (typeof node.type !== "string") {
    return false
  }
  if (node.text !== undefined && typeof node.text !== "string") {
    return false
  }
  if (node.content !== undefined) {
    if (!Array.isArray(node.content)) {
      return false
    }
    return node.content.every((child) => isTiptapDoc(child, depth + 1))
  }
  return true
}

export interface ImportedNote {
  title: string | null
  content: unknown
}

/** Parses an uploaded .md/.txt/.json file into editor-ready content. */
export function parseImportFile(fileName: string, raw: string): ImportedNote {
  const lower = fileName.toLowerCase()
  if (lower.endsWith(".json")) {
    let parsed: unknown
    try {
      parsed = JSON.parse(raw)
    } catch {
      throw new Error("IMPORT_INVALID_JSON")
    }
    const checked = backupSchema.safeParse(parsed)
    if (!checked.success) {
      throw new Error("IMPORT_INVALID_JSON")
    }
    const doc = checked.data.content
    if (!isTiptapDoc(doc)) {
      throw new Error("IMPORT_INVALID_JSON")
    }
    return { title: checked.data.title ?? null, content: doc }
  }

  // .md and .txt both go through the markdown converter (plain text is a
  // markdown subset — every line just becomes a paragraph).
  return { title: null, content: markdownToDoc(raw) }
}

// ---------------------------------------------------------------------------
// Minimal markdown → Tiptap converter (blocks + common inline marks)
// ---------------------------------------------------------------------------

function parseInlineMarks(text: string): TiptapNode[] {
  const pattern =
    /(\*\*([^*]+)\*\*)|(\*([^*]+)\*)|(`([^`]+)`)|(~~([^~]+)~~)/
  const match = text.match(pattern)
  if (!match) {
    return text ? [{ type: "text", text }] : []
  }
  const [full, , bold, , italic, , code, , strike] = match
  const before = text.slice(0, match.index)
  const after = text.slice((match.index ?? 0) + full.length)

  let marked: TiptapNode
  if (bold !== undefined) {
    marked = { type: "text", marks: [{ type: "bold" }], text: bold }
  } else if (italic !== undefined) {
    marked = { type: "text", marks: [{ type: "italic" }], text: italic }
  } else if (code !== undefined) {
    marked = { type: "text", marks: [{ type: "code" }], text: code }
  } else {
    marked = { type: "text", marks: [{ type: "strike" }], text: strike ?? "" }
  }

  return [
    ...parseInlineMarks(before),
    marked,
    ...parseInlineMarks(after),
  ]
}

function paragraph(text: string): TiptapNode {
  return { type: "paragraph", content: parseInlineMarks(text) }
}

export function markdownToDoc(raw: string): unknown {
  const lines = raw.replace(/\r\n/g, "\n").split("\n")
  const top: TiptapNode[] = []
  let inCode = false
  let codeLines: string[] = []
  let paraBuffer: string[] = []

  const flushParagraph = () => {
    if (paraBuffer.length > 0) {
      top.push(paragraph(paraBuffer.join(" ")))
      paraBuffer = []
    }
  }

  for (const line of lines) {
    if (inCode) {
      if (/^```/.test(line)) {
        top.push({ type: "codeBlock", content: codeLines.map((l) => ({ type: "text", text: l })) })
        codeLines = []
        inCode = false
      } else {
        codeLines.push(line)
      }
      continue
    }

    const heading = line.match(/^(#{1,6})\s+(.*)$/)
    const bullet = line.match(/^[-*]\s+(.*)$/)
    const ordered = line.match(/^\d+[.)]\s+(.*)$/)
    const quote = line.match(/^>\s?(.*)$/)

    if (/^```/.test(line)) {
      flushParagraph()
      inCode = true
    } else if (heading) {
      flushParagraph()
      top.push({
        type: "heading",
        attrs: { level: heading[1]!.length },
        content: parseInlineMarks(heading[2] ?? ""),
      })
    } else if (line.trim() === "---") {
      flushParagraph()
      top.push({ type: "horizontalRule" })
    } else if (quote) {
      flushParagraph()
      top.push({ type: "blockquote", content: [paragraph(quote[1] ?? "")] })
    } else if (bullet) {
      flushParagraph()
      top.push({
        type: "bulletList",
        content: [{ type: "listItem", content: [paragraph(bullet[1] ?? "")] }],
      })
    } else if (ordered) {
      flushParagraph()
      top.push({
        type: "orderedList",
        content: [{ type: "listItem", content: [paragraph(ordered[1] ?? "")] }],
      })
    } else if (line.trim() === "") {
      flushParagraph()
    } else {
      paraBuffer.push(line.trim())
    }
  }
  if (inCode && codeLines.length > 0) {
    top.push({ type: "codeBlock", content: codeLines.map((l) => ({ type: "text", text: l })) })
  }
  flushParagraph()

  return { type: "doc", content: top }
}

/** Flattens a doc to plain text — used by the revision diff viewer. */
export function docToDiffText(doc: unknown): string {
  return toPlainText(doc)
}
